import numpy as np
from math import pi, sqrt
rng=np.random.default_rng(56)

def perp(n):
 a=np.array([1.,0.,0.]) if abs(n[0])<.8 else np.array([0.,1.,0.])
 u=np.cross(n,a);u/=np.linalg.norm(u)
 return u,np.cross(n,u)

def tripod(n,phase):
 u,v=perp(n)
 return [n/3+sqrt(8/9)*(np.cos(phase+2*pi*k/3)*u+np.sin(phase+2*pi*k/3)*v) for k in range(3)]

def make():
 els=['Ni'];xyz=[np.zeros(3)];bonds=[]
 ligs=[('Si',np.array([.5,sqrt(3)/2,0.])),('Si',np.array([.5,-sqrt(3)/2,0.])),('P',np.array([-1.,0.,0.])),('P',np.array([0.,0.,1.])),('P',np.array([0.,0.,-1.]))]
 for el,n in ligs:
  i=len(els);q=n*(2.28 if el=='Si' else 2.25);els.append(el);xyz.append(q);bonds.append((0,i))
  for d in tripod(n,rng.uniform(0,2*pi)):
   j=len(els);c=q+(1.60 if el=='Si' else 1.84)*d
   els.append('F' if el=='Si' else 'C');xyz.append(c);bonds.append((i,j))
   if el=='P':
    for h in tripod(d,rng.uniform(0,2*pi)):
     k=len(els);els.append('H');xyz.append(c+1.095*h);bonds.append((j,k))
 return els,np.array(xyz),bonds
best=None
radii={'Ni':1.4,'Si':1.6,'P':1.6,'C':1.6,'F':1.35,'H':1.0}
for _ in range(500):
 els,xyz,bonds=make()
 n=len(els);excl=set(tuple(sorted(b)) for b in bonds)
 for a,b in bonds:
  for c,d in bonds:
   if b==c:excl.add(tuple(sorted((a,d))))
   if a==c:excl.add(tuple(sorted((b,d))))
 inds=[(i,j) for i in range(n) for j in range(i+1,n) if (i,j) not in excl]
 cost=sum(max(0,radii[els[i]]+radii[els[j]]-np.linalg.norm(xyz[i]-xyz[j]))**2 for i,j in inds)
 if best is None or cost<best[0]:best=(cost,els,xyz,bonds)
_,els,xyz,bonds=best
with open('initial.xyz','w') as f:
 f.write(f'{len(els)}\nNi(SiF3)2(PMe3)3; explicit hydrogens\n')
 for el,p in zip(els,xyz):f.write(f'{el:2s} {p[0]: .8f} {p[1]: .8f} {p[2]: .8f}\n')
print('Atom count:',len(els),'Steric penalty:',best[0])
print('Ni ligand atoms (1 based):',[(i+1,els[i]) for a,i in bonds if a==0])
